const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const URL = 'http://localhost:3002/index.html';
const KEY = 'stillwater-cultivator-v1';
const save = {
  lastSeen: Date.now(), qi: 250000, stones: 25000, hp: 5000, maxHp: 5000, totalSeconds: 12000,
  spirit: { realm: 8, stage: 6, breaks: 4, criticals: 1, failures: 1, bonuses: { qi: 1, spell: 1, dao: 1 } },
  body: { realm: 6, stage: 4, unlocked: true, breaks: 3, criticals: 0, failures: 0, bonuses: { hp: 1, attack: 1, guard: 1 } },
  origin: { unlocked: false, level: 0, name: 'Beyond the Origin' },
  sectRank: 3, sectRep: 150, sectTokens: 120, sect: 'azure',
  equipment: {}, arts: { cloudpalm: 1, flameserpent: 2 }, pathLevels: { spirit: 8, body: 6 }, upgrades: {}
};
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 1000 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  const errs = []; page.on('pageerror', e => errs.push(e.message));
  await page.goto(URL, { waitUntil: 'networkidle' });
  await page.evaluate(([k, o]) => localStorage.setItem(k, JSON.stringify(o)), [KEY, save]);
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(600);
  const views = ['paths', 'combat', 'sect', 'techniques', 'ascension', 'codex'];
  for (const v of views) {
    await page.locator(`.nav-item[data-view="${v}"]`).click();
    await page.waitForTimeout(350);
    await page.screenshot({ path: `/tmp/opencode/shots/view-${v}.jpg`, type: 'jpeg', quality: 70 });
  }
  console.log('errors', errs);
  await browser.close();
})();

