const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const URL = 'http://localhost:3002/index.html';
const KEY = 'stillwater-cultivator-v1';
const errors = [];
const fail = m => { errors.push(m); console.log('FAIL', m); };
const ok = m => console.log('ok', m);

const mid = {
  lastSeen: Date.now(), qi: 5000000, stones: 50000, totalSeconds: 9000, hp: 3000, maxHp: 3000,
  spirit: { realm: 9, stage: 5, breaks: 4, criticals: 1, failures: 1, bonuses: { qi: 2, spell: 1, dao: 1 } },
