  equipment: {}, arts: { cloudpalm: 1, flameserpent: 1, thunderstep: 1 }, activeArts: ['cloudpalm', 'flameserpent'], artRanks: { cloudpalm: 3, flameserpent: 2 },
  pathLevels: { spirit: 12, body: 8 }, upgrades: { sutra: 2, body: 1, alchemy: 2, beast: 1 },
  herbs: { herb: 20, root: 20, flower: 20, ore: 20, essence: 20, crystal: 20, beastCore: 5, voidDust: 5, relic: 5 },
  brews: 8, root: { type: 'fire', grade: 2, essence: 10 }, meridianPoints: 2,
  meridians: { points: 2, opened: { lung: true, heart: true } },
  dao: { fire: { xp: 800 }, water: { xp: 300 }, sword: { xp: 500 } }, daoPoints: 4,
  taming: { beasts: { mistwolf: { level: 3, bond: 10 } }, active: 'mistwolf', food: 5 },
  inheritance: { discovered: [], trials: {}, completed: [] },
  forge: { weapons: { pineblade: { refine: 2, temper: 1 } }, equippedWeapon: 'pineblade', equippedArtifacts: [null, null] },
  arena: { rank: 10, wins: 0, fought: {} },
  fate: { pending: null, log: [], merchant: [], merchantDate: 0, merchantRefreshDate: 0, maps: 2, fragments: 5, clock: 0, encounters: 0, luckBuff: 0, luckBuffUntil: 0, offeringLuck: 0, offeringUntil: 0, divinations: 0 },
  achievements: {}, notifications: [], stats: { kills: 3, bosses: 0, realms: 0, chests: 1 },
  missions: { progress: {}, claimed: [] }, dailies: { progress: {}, claimed: [], date: 0 },
  quests: { active: null, progress: {}, completed: [] }, story: {}
};

(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 1000 } });
  const page = await ctx.newPage();
  page.on('pageerror', e => fail('pageerror: ' + e.message));
  await page.addInitScript(() => { window.setInterval = () => 0; });
  await page.goto(URL, { waitUntil: 'networkidle' });

  // Fresh game: meditate and progress.
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'networkidle' });
  const before = await page.locator('#qiText').innerText();
  await page.locator('#meditateBtn').click();
  await page.waitForTimeout(1200);
  const after = await page.locator('#qiText').innerText();
  if (!(parseInt(after.replace(/,/g, ''), 10) > parseInt(before.replace(/,/g, ''), 10))) fail(`meditation did not add qi (${before} -> ${after})`);
  else ok('meditation gathers qi');

  // Seed midgame.
  await page.evaluate(([k, o]) => { localStorage.setItem(k, JSON.stringify(o)); Storage.prototype.setItem = function () {}; }, [KEY, mid]);
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(300);

  const views = ['cultivate','paths','dao','combat','sect','techniques','expeditions','alchemy','inherit','forge','fate','ascension','codex'];
  for (const v of views) {
    await page.locator(`.nav-item[data-view="${v}"]`).first().click();
    await page.waitForTimeout(150);
    const visible = await page.locator(`#view-${v}`).isVisible();
    if (!visible) fail(`view ${v} not visible`);
    const text = await page.locator(`#view-${v}`).innerText();
    if (text.trim().length < 50) fail(`view ${v} looks empty (${text.trim().length})`);
    ok(`view ${v} renders (${text.trim().length} chars)`);
  }

  // Arena duel flow.
  await page.locator('.nav-item[data-view="sect"]').click();
  await page.locator('[data-tab="arena"]').first().click().catch(() => {});
  await page.waitForTimeout(200);
  const challenge = page.locator('[data-action="challenge-rival"]:not([disabled])').first();
  if (await challenge.count()) {
    await challenge.click(); await page.waitForTimeout(250);
    const attack = page.locator('[data-action="arena-attack"]').first();
    if (!(await attack.count())) fail('arena battle has no attack action');
    else {
      for (let i = 0; i < 25; i++) {
        const alive = await page.locator('[data-action="arena-attack"]').count();
        if (!alive) break;
        await page.locator('[data-action="arena-attack"]').first().click().catch(() => {});
        await page.waitForTimeout(40);
      }
      ok('arena duel can be fought');
    }
  } else fail('no arena challenge available at seeded rank');

  // Combat: seek and strike.
  await page.locator('.nav-item[data-view="combat"]').click();
  await page.locator('[data-action="seek-beast"]').first().click().catch(() => {});
  await page.waitForTimeout(250);
  const strike = page.locator('[data-action="attack"]').first();
  if (await strike.count()) {
    await strike.click(); await page.waitForTimeout(120);
    ok('beast combat strike works');
  } else fail('no beast attack button after seeking');

  // Forge: forge/equip another weapon if possible.
  await page.locator('.nav-item[data-view="forge"]').click();
  await page.waitForTimeout(150);
  const forgeBtn = page.locator('[data-action="forge-weapon"]:not([disabled])').first();
  if (await forgeBtn.count()) { await forgeBtn.click(); await page.waitForTimeout(200); ok('forging works'); }
  else ok('forge shows no forgeable weapon (state-dependent)');

  // Fate: seek a fortune.
  await page.locator('.nav-item[data-view="fate"]').click();
  await page.waitForTimeout(150);
  const seek = page.locator('[data-action="seek-fate"]:not([disabled])').first();
  if (await seek.count()) { await seek.click(); await page.waitForTimeout(200); ok('fate seek works'); }

  // Alchemy: brew.
  await page.locator('.nav-item[data-view="alchemy"]').click();
  await page.waitForTimeout(150);
  const brew = page.locator('[data-action="brew"]:not([disabled])').first();
  if (await brew.count()) { await brew.click(); await page.waitForTimeout(200); ok('alchemy brewing works'); }
  else ok('alchemy shows no brewable recipe (state-dependent)');

  console.log(errors.length ? `${errors.length} FAILURE(S)` : 'ALL QA PASSED');
  await browser.close();
  process.exit(errors.length ? 1 : 0);
})();

