content.text:
34:.feature-stats{display:flex;flex-wrap:wrap;gap:8px 18px;padding-top:12px;border-top:1px solid rgba(220,229,212,.16)}
35:.feature-stats span{display:grid;gap:4px;color:#aab8a9;font-size:8px;letter-spacing:.65px}
36:.feature-stats b{color:#e5d7a9;font-size:11px;letter-spacing:0}
123:.banner-card{display:flex;align-items:center;gap:14px;padding:13px 17px;border:1px solid #e4dcc4;border-radius:9px;background:linear-gradient(120deg,#fbf5e5,#fffefa);box-shadow:var(--shadow)}
124:.banner-card.fate{border-color:#bfd4c1;background:linear-gradient(120deg,#edf5ea,#fffefa)}
125:.banner-card.event{border-color:#d8c692;background:linear-gradient(120deg,#f8efd5,#fffefa)}
126:.banner-symbol{width:38px;height:38px;flex-shrink:0;display:grid;place-items:center;border-radius:50%;border:1px solid #e0d3ae;background:#faf4e1;color:#9b7c38;font:20px 'Ma Shan Zheng',serif}
127:.banner-card.fate .banner-symbol{background:#eaf3e7;border-color:#c6d9c4;color:#4b7b5c}
128:.banner-body{flex:1;min-width:0}
129:.banner-body small{display:block;font-size:7px;letter-spacing:1.1px;color:#9a927d;margin-bottom:3px;font-weight:700}
130:.banner-body b{display:block;font:600 13px var(--serif);color:#4e5547}
131:.banner-body span{display:block;font-size:9px;color:#89907f;line-height:1.45;margin-top:2px}
132:.banner-card .action-btn,.banner-card .buy-btn{flex-shrink:0;white-space:nowrap}
378:.gold-text{color:#9a7d3c;font-weight:700}
.circulation-bonus h3{margin:0 0 5px;font:600 14px var(--serif);color:#42644f}
.circulation-bonus p{margin:0;color:#7b8b7d;font-size:9px;line-height:1.6}

/* Dao comprehension */
.dao-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px;margin-top:13px}
.dao-card{position:relative;padding:16px;border:1px solid #e8e8df;border-radius:9px;background:linear-gradient(150deg,#fffefa,#fbfaf3);overflow:hidden}
.dao-card:before{content:"";position:absolute;inset:0 0 auto;height:3px;background:var(--dao,#8aa28b)}
.dao-head{display:flex;align-items:center;gap:11px;margin-bottom:9px}
.dao-seal{width:39px;height:39px;flex-shrink:0;display:grid;place-items:center;border-radius:50%;border:1px solid var(--dao,#9db29e);background:#f6f8f2;color:var(--dao,#547a60);font:21px 'Ma Shan Zheng',serif}
.dao-head h3{margin:0;font:600 15px var(--serif);color:#3b5144}
.dao-head small{display:block;font-size:7px;letter-spacing:.8px;color:#929b91;margin-top:2px}
.dao-card p{margin:0 0 9px;color:#7c887f;font-size:9px;line-height:1.55;min-height:28px}
.dao-ability{font-size:8px;line-height:1.45;color:#8a7952;border-top:1px dashed #e8e2d0;padding-top:7px;margin-top:7px}
.dao-ability b{color:#6e643f}
.dao-actions{display:flex;gap:6px;margin-top:10px;flex-wrap:wrap}
.dao-actions .action-btn{flex:1 1 100px;padding:7px 6px;font-size:8px;white-space:normal;line-height:1.3}

/* Beasts and bosses */
.beast-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:12px}
.beast-card{display:flex;flex-direction:column;align-items:flex-start;min-width:0;padding:13px;border:1px solid #e8e8df;border-radius:8px;background:#fffefa}
.beast-card.active{border-color:#8fb695;background:linear-gradient(150deg,#f1f8ee,#fffefa);box-shadow:inset 0 0 0 1px rgba(90,133,98,.12)}
.beast-card.tamed{border-color:#d9d2b6}
.beast-glyph{width:42px;height:42px;display:grid;place-items:center;border-radius:50%;border:1px solid var(--rarity,#ddd6c4);background:radial-gradient(circle,#fffdf5,#f3eddd);color:var(--rarity,#8b7b58);font:23px 'Ma Shan Zheng',serif;margin-bottom:7px}
.beast-card h3{margin:0 0 3px;font:600 12px var(--serif);color:#3b5144;line-height:1.25}
.beast-card p{margin:0 0 7px;color:#7f8a80;font-size:8px;line-height:1.45}
.beast-card .rarity-tag{font-size:7px;letter-spacing:1px;font-weight:700;color:var(--rarity,#8b7b58);margin-bottom:3px}
.beast-card .action-btn{width:100%;margin-top:auto;padding:7px 4px;font-size:8px;white-space:normal;line-height:1.3}
.beast-bonus{font-size:7.5px;color:#8a7952;line-height:1.45;margin-bottom:7px}
.boss-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px;margin-top:12px}
.boss-card{padding:15px;border:1px solid #e8e8df;border-radius:9px;background:linear-gradient(150deg,#fffefa,#faf7ef)}
.boss-card.defeated{border-color:#c9dcc7;background:linear-gradient(150deg,#f3f8ef,#fffefa)}
.boss-card.locked{opacity:.66}
.boss-card h3{margin:0 0 4px;font:600 15px var(--serif);color:#3b5144}
.boss-card p{margin:0 0 8px;color:#7f8a80;font-size:9px;line-height:1.5}
.boss-ability{font-size:8px;color:#9b6c4e;line-height:1.45;margin-bottom:8px}
.boss-reward{font-size:8px;color:#8a7952;line-height:1.45;margin-bottom:8px}
.boss-card .action-btn{width:100%;white-space:normal}
.boss-battle{margin-top:15px;padding:18px;border:1px solid #e4d3ab;border-radius:9px;background:linear-gradient(135deg,#fdf8e8,#fffefa)}
.boss-head{display:flex;align-items:center;gap:14px;margin-bottom:12px}
.boss-glyph{width:70px;height:70px;flex-shrink:0;display:grid;place-items:center;border-radius:50%;border:1px solid #e0c98d;background:radial-gradient(circle,#fffdf2,#f3e8cd);color:#9e7b2d;font:36px 'Ma Shan Zheng',serif}
.boss-head h3{margin:0 0 4px;font:600 20px var(--serif)}
.boss-head small{display:block;font-size:7px;letter-spacing:1px;color:#a08850;font-weight:700;margin-bottom:4px}
.boss-actions{display:flex;flex-wrap:wrap;gap:7px;margin-top:13px}
.boss-actions .action-btn{flex:1 1 120px;font-size:8px;white-space:normal;line-height:1.35}
.battle-log{margin-top:12px;padding:9px 11px;border:1px solid #ece5d4;border-radius:6px;background:#fffdf6;font-size:8px;line-height:1.6;color:#8a8573;max-height:90px;overflow:auto}
.battle-log b{color:#655c45}

/* Inheritance + secret realms */
.legacy-grid{display:grid;gap:12px;margin-top:12px}
.legacy-card{padding:16px;border:1px solid #e8e1cf;border-radius:9px;background:linear-gradient(135deg,#fdfaf0,#fffefa)}
.legacy-card.discovered{border-color:#d6c79d;box-shadow:0 8px 24px rgba(126,102,42,.06)}
.legacy-card.completed{border-color:#b9d2ba;background:linear-gradient(135deg,#f3f8ef,#fffefa)}
.legacy-head{display:flex;align-items:center;gap:12px;margin-bottom:10px}
.legacy-seal{width:44px;height:44px;flex-shrink:0;display:grid;place-items:center;border-radius:50%;border:1px solid #dfd2ab;background:#fbf5e3;color:#9e7b2d;font:23px 'Ma Shan Zheng',serif}
.legacy-head h3{margin:0;font:600 16px var(--serif);color:#3e4d3f}
.legacy-head small{display:block;font-size:7px;letter-spacing:.9px;color:#9a927d;margin-top:2px}
.legacy-card>p{margin:0 0 10px;color:#7c887f;font-size:9px;line-height:1.55}
.trial-list{display:grid;gap:6px;margin:10px 0}
.trial-row{display:flex;align-items:center;gap:9px;padding:8px 10px;border:1px solid #ece7d8;border-radius:6px;background:#fffefa;font-size:8px;color:#7f8578}
.trial-row.done{border-color:#cfe0cc;background:#f3f8f0;color:#5d7a63}
.trial-check{width:19px;height:19px;flex-shrink:0;display:grid;place-items:center;border-radius:50%;border:1px solid #ddd8c8;color:#b3ab97;font-size:9px}
.trial-row.done .trial-check{border-color:#b9d2ba;background:#e6f1e4;color:#4b7559}
.trial-row div{flex:1;min-width:0}
.trial-row b{display:block;font-size:9px;color:#4f5d50;margin-bottom:1px}
.trial-row small{font-size:7px;color:#90998d;line-height:1.4}
.trial-row .action-btn{padding:5px 8px;font-size:7px;white-space:nowrap}
.realm-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px;margin-top:12px}
.realm-card{padding:15px;border:1px solid #e8e8df;border-radius:9px;background:linear-gradient(150deg,#fffefa,#f9f7ef)}
.realm-card.cleared{border-color:#c9dcc7;background:linear-gradient(150deg,#f2f8ee,#fffefa)}
.realm-card.locked{opacity:.65}
.realm-card h3{margin:0 0 4px;font:600 15px var(--serif)}

