const KEY='stillwater-cultivator-v1', URL='http://localhost:3002/index.html';
const errs=[]; const must=(c,m)=>{if(!c){errs.push(m);console.log('FAIL',m)}else console.log('ok',m)};
(async()=>{
 const b=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox']});
 const ctx=await b.newContext({viewport:{width:1280,height:1000}}); const p=await ctx.newPage();
 p.on('pageerror',e=>errs.push('pageerror '+e.message));
 await p.goto(URL,{waitUntil:'networkidle'});
 const base={lastSeen:Date.now(),qi:12000000,stones:50000,totalSeconds:4800,hp:5000,maxHp:5000,spirit:{realm:14,stage:9,breaks:20,criticals:5,failures:1,bonuses:{qi:5,spell:5,dao:5}},body:{realm:14,stage:9,unlocked:true,breaks:20,criticals:5,failures:0,bonuses:{hp:5,attack:5,guard:5}},origin:{unlocked:true,level:9,name:'Beyond the Origin'},sectRank:4,sectRep:260,sectTokens:300,sectId:'azure',upgrades:{sutra:4,body:3,alchemy:2,beast:2,dao:2},pathLevels:{spirit:15,body:12},root:{type:'divine',grade:3,essence:10},meridians:{points:0,opened:{lung:true,heart:true,liver:true,spleen:true,kidney:true,pericardium:true,triple:true,governing:true,conception:true,chong:true,dai:true,yangwei:true}},dao:{fire:{xp:5000},water:{xp:5000},sword:{xp:5000},life:{xp:5000},lightning:{xp:5000},space:{xp:5000}},daoPoints:3,taming:{beasts:{mistwolf:{level:5,bond:40}},active:'mistwolf'},forge:{weapons:{},equippedArtifacts:[]},arena:{rank:1,wins:10},fate:{pending:null,log:[],merchant:[],maps:0,fragments:0},achievements:{},stats:{kills:123,bosses:5,realms:6,chests:3},rebirth:{count:2,points:3,world:1,upgrades:{qi:1,attack:1,luck:1,dao:1}}};
 await p.evaluate(([k,o])=>{localStorage.setItem(k,JSON.stringify(o));Storage.prototype.setItem=function(){}},[KEY,base]);
 await p.reload({waitUntil:'networkidle'}); await p.waitForTimeout(250);
 await p.locator('.nav-item[data-view="paths"]').click(); await p.waitForTimeout(250);
 must(/Beyond the Origin/.test(await p.locator('.origin-card').innerText()),'origin card shows');
 await p.screenshot({path:'/tmp/opencode/shots/origin-ready.jpg',type:'jpeg',quality:70});
 await p.locator('.origin-card [data-action="advance-origin"]').click(); await p.waitForTimeout(500);
 const modal=await p.locator('#modalText').innerText();
 must(/journey is complete|The journey is complete/i.test(await p.locator('#modalTitle').innerText()) || /THE END OF ALL ROADS/i.test(await p.locator('#modalEyebrow').innerText()),'ending modal opens');
 must(/DAY/.test(modal)&&/ACHIEVEMENTS/.test(modal),'ending modal shows summary');
 must(/50000|50,000/.test(await p.locator('#stones').innerText()),'ending achievement reward applied');
 const saved=await p.evaluate(k=>JSON.parse(localStorage.getItem(k)),KEY);
 must(saved.ending && saved.ending.complete===true,'ending completion saved');
 must(saved.achievements && saved.achievements.ending===true,'ending achievement unlocked');
 await p.screenshot({path:'/tmp/opencode/shots/ending-modal.jpg',type:'jpeg',quality:70});
 await p.locator('#modalActions [data-action="close-modal"]').click(); await p.waitForTimeout(200);
 must(await p.locator('#completionBadge').isVisible(),'completion badge visible');
 await p.locator('.nav-item[data-view="cultivate"]').click(); await p.waitForTimeout(250);
 must(/JOURNEY COMPLETE/.test(await p.locator('#eventBanners').innerText()),'completion banner visible');
 await p.locator('#eventBanners [data-action="show-ending"]').click(); await p.waitForTimeout(200);
 must(await p.locator('#modalBackdrop').isVisible(),'banner reopens ending');
 await p.locator('#modalActions [data-action="close-modal"]').click();
 await p.locator('.nav-item[data-view="ascension"]').click(); await p.waitForTimeout(250);
 must(/Your legend is finished/.test(await p.locator('#view-ascension').innerText()),'ascension ending card visible');
 await p.screenshot({path:'/tmp/opencode/shots/ending-ascension.jpg',type:'jpeg',quality:70});
 // Reload persistence
 await p.reload({waitUntil:'networkidle'}); await p.waitForTimeout(200);
 must(await p.locator('#completionBadge').isVisible(),'completion badge persists after reload');
 console.log(errs.length?`${errs.length} FAILURE(S)`:'ALL ENDING TESTS PASSED');
 await b.close(); process.exit(errs.length?1:0);
})();

